<template><div class="page"><h2 class="page-title">账单与消费分类</h2><p class="muted">当前支持微信.xlsx；支付宝和银行卡将在后续版本开放。</p><div class="card section"><el-upload drag :auto-upload="false" :limit="1" accept=".xlsx" :on-change="f=>selected=f.raw"><p>拖入或选择微信账单</p><small>原文件仅临时解析，导入完成后删除</small></el-upload><el-button class="section" type="primary" :loading="uploading" :disabled="!selected" @click="upload">开始导入</el-button><el-descriptions v-if="report" class="section" border :column="4"><el-descriptions-item label="总记录">{{report.total_rows}}</el-descriptions-item><el-descriptions-item label="新增">{{report.inserted_rows}}</el-descriptions-item><el-descriptions-item label="重复">{{report.duplicate_rows}}</el-descriptions-item><el-descriptions-item label="失败/警告">{{report.failed_rows}} / {{report.warning_rows}}</el-descriptions-item><el-descriptions-item label="消费">{{report.flow_type_counts?.consumption||0}}</el-descriptions-item><el-descriptions-item label="退款">{{report.refund_rows}}</el-descriptions-item><el-descriptions-item label="转账">{{report.transfer_rows}}</el-descriptions-item><el-descriptions-item label="其他/未知">{{report.unknown_flow_rows}}</el-descriptions-item><el-descriptions-item label="导入时未分类笔数">{{formatRatio(report.uncategorized_consumption_ratio)}}</el-descriptions-item><el-descriptions-item label="导入时未分类金额">{{formatRatio(report.uncategorized_consumption_amount_ratio)}}</el-descriptions-item><el-descriptions-item label="起始时间">{{report.earliest_transaction_time||'暂无'}}</el-descriptions-item><el-descriptions-item label="结束时间">{{report.latest_transaction_time||'暂无'}}</el-descriptions-item></el-descriptions></div><div class="card section"><h3>导入历史</h3><el-table :data="imports" empty-text="尚未导入账单"><el-table-column prop="started_at" label="导入时间"/><el-table-column prop="source" label="来源"/><el-table-column prop="status" label="状态"/><el-table-column prop="inserted_rows" label="新增"/><el-table-column prop="duplicate_rows" label="重复"/><el-table-column prop="failed_rows" label="失败"/></el-table></div><div class="card section"><div class="actions"><h3 style="flex:1">OTHER 人工审核</h3><el-button v-if="deepseek?.ready" :loading="aiLoading" @click="requestSuggestions('A')">DeepSeek分析A级</el-button><el-button v-if="deepseek?.ready" :loading="aiLoading" @click="requestSuggestions('B')">DeepSeek分析B级</el-button></div><el-alert v-if="reviewSummary" :title="`当前OTHER：${reviewSummary.current_other_count}笔（${formatRatio(reviewSummary.current_other_count_ratio)}），${formatMoney(reviewSummary.current_other_amount_minor)}（${formatRatio(reviewSummary.current_other_amount_ratio)}）`" type="info" :closable="false"/><el-alert class="section" :type="deepseek?.ready?'warning':'info'" :closable="false" :title="deepseek?.ready?`DeepSeek ${deepseek.model} 已就绪；每次发送前都会请你确认`:'DeepSeek尚未在本地配置，当前仅使用规则和人工确认'"/><p class="muted">A级优先确认，B级建议确认，C级可保留OTHER。DeepSeek只给候选类别，不会自动改标签；个人二维码默认不发送。</p><el-table :data="reviews" empty-text="当前没有带文本的审核队列；重新选择原账单可生成，重复交易不会入库"><el-table-column prop="tier" label="层级" width="70"/><el-table-column prop="merchant_hint" label="商户短文本" min-width="180"/><el-table-column prop="description_hint" label="说明短文本" min-width="180"/><el-table-column prop="dominant_time_bucket" label="常见时段"/><el-table-column prop="transaction_count" label="笔数"/><el-table-column label="金额"><template #default="s">{{formatMoney(s.row.amount_minor)}}</template></el-table-column><el-table-column label="DeepSeek候选" min-width="200"><template #default="s"><template v-if="s.row.model_suggestion"><el-tag :type="s.row.model_suggestion.category_code==='other'?'info':'warning'">{{categoryName(s.row.model_suggestion.category_code)}} {{s.row.model_suggestion.confidence.toFixed(0)}}%</el-tag><div class="section" v-if="s.row.model_suggestion.category_code!=='other'"><el-button size="small" type="primary" @click="acceptSuggestion(s.row.model_suggestion)">接受</el-button><el-button size="small" @click="rejectSuggestion(s.row.model_suggestion)">拒绝</el-button></div><small v-else class="muted">证据不足，建议保留</small></template><span v-else class="muted">未分析</span></template></el-table-column><el-table-column label="人工确认" min-width="150"><template #default="s"><el-select placeholder="选择类别" @change="v=>confirmReview(s.row,v)"><el-option v-for="c in categories.filter(x=>x.code!=='other')" :key="c.code" :label="c.name" :value="c.code"/></el-select></template></el-table-column></el-table></div><div class="card section"><div class="actions"><h3 style="flex:1">标准交易记录</h3><el-button @click="load">刷新</el-button></div><el-table :data="transactions"><el-table-column prop="occurred_at" label="时间" width="180"/><el-table-column label="金额"><template #default="s">{{formatMoney(s.row.amount_minor)}}</template></el-table-column><el-table-column prop="direction" label="方向"/><el-table-column prop="flow_type" label="类型"/><el-table-column prop="source" label="来源"/><el-table-column prop="status" label="状态"/><el-table-column label="分类"><template #default="s"><el-select :model-value="s.row.effective_category" @change="v=>changeCategory(s.row,v)"><el-option v-for="c in categories" :key="c.code" :label="c.name" :value="c.code"/></el-select><el-tag v-if="s.row.user_confirmed" size="small" type="success">用户已确认</el-tag></template></el-table-column></el-table></div></div></template>
<script setup>
import { onMounted,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js'
const selected=ref(),uploading=ref(false),aiLoading=ref(false),report=ref(),transactions=ref([]),categories=ref([]),imports=ref([]),reviews=ref([]),reviewSummary=ref(),deepseek=ref()
const formatRatio=value=>`${((value||0)*100).toFixed(1)}%`
async function load(){const [t,c,i,r,d]=await Promise.all([api.get('/transactions?page_size=100'),api.get('/categories'),api.get('/imports'),api.get('/categories/review'),api.get('/classification/providers/deepseek')]);transactions.value=t.items;categories.value=c.items;imports.value=i.items;reviews.value=r.items;reviewSummary.value=r.summary;deepseek.value=d}
async function upload(){const body=new FormData();body.append('file',selected.value);uploading.value=true;try{report.value=await api.post('/imports/wechat',body,{timeout:120000});ElMessage.success('导入完成');await load()}catch(e){ElMessage.error(e.message);if(e.code==='REQUEST_TIMEOUT')await load()}finally{uploading.value=false}}
async function changeCategory(row,code){try{await api.patch(`/transactions/${row.id}/category`,{category_code:code});row.effective_category=code;row.user_confirmed=true;ElMessage.success('分类已确认')}catch(e){ElMessage.error(e.message)}}
async function confirmReview(row,code){try{const r=await api.patch(`/transactions/${row.representative_transaction_id}/category`,{category_code:code});ElMessage.success(`已确认并应用到同组 ${r.updated_transactions} 笔交易`);await load()}catch(e){ElMessage.error(e.message)}}
const categoryName=code=>categories.value.find(x=>x.code===code)?.name||code
async function requestSuggestions(tier){try{await ElMessageBox.confirm(`将向DeepSeek发送最多${tier==='A'?10:20}个${tier}级商户组的脱敏短文本、金额区间、时段和频次区间。个人二维码会自动跳过。是否继续？`,'隐私确认',{type:'warning',confirmButtonText:'同意并分析',cancelButtonText:'取消'});aiLoading.value=true;const r=await api.post('/categories/review/deepseek-suggestions',{tier,limit:tier==='A'?10:20},{timeout:120000});ElMessage.success(`已生成 ${r.created} 个候选，跳过 ${r.skipped_private} 个隐私或语义不足组`);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'已取消')}finally{aiLoading.value=false}}
async function acceptSuggestion(item){try{const r=await api.post(`/categories/suggestions/${item.id}/accept`);ElMessage.success(`已人工接受，应用到同组 ${r.updated_transactions} 笔交易`);await load()}catch(e){ElMessage.error(e.message)}}
async function rejectSuggestion(item){try{await api.post(`/categories/suggestions/${item.id}/reject`);ElMessage.success('已拒绝该模型建议');await load()}catch(e){ElMessage.error(e.message)}}
onMounted(load)
</script>
